        if (this.size * 3 >= this.heap.length) {
            const nextHeap = new Int32Array(this.heap.length * 2);
            nextHeap.set(this.heap);
            this.heap = nextHeap;
        }

        let i = this.size++;
        this.heap[i * 3] = time;
        this.heap[i * 3 + 1] = u;
        this.heap[i * 3 + 2] = cost;

