            const p = (i - 1) >> 1;
            if (this.heap[p * 3] > this.heap[i * 3]) {
                const t0 = this.heap[p * 3];
                const t1 = this.heap[p * 3 + 1];
                const t2 = this.heap[p * 3 + 2];

                this.heap[p * 3] = this.heap[i * 3];
                this.heap[p * 3 + 1] = this.heap[i * 3 + 1];
                this.heap[p * 3 + 2] = this.heap[i * 3 + 2];

                this.heap[i * 3] = t0;
                this.heap[i * 3 + 1] = t1;
                this.heap[i * 3 + 2] = t2;

                i = p;
            } else {
                break;
            }
        }
    }

