        const u = readInt();
        const v = readInt();
        const t = readInt();
        const p = readInt();
        addEdge(u, v, t, p);
        addEdge(v, u, t, p);
    }

    const X = readInt();
    const Y = readInt();

    if (X === Y) {
        console.log(0);
        return;
    }

    const V1 = V + 1;
    const totalStates = (N + 1) * V1;
    const dist = new Int32Array(totalStates).fill(1061109567); // ~0x3f3f3f3f

    const pq = new MinHeap(1024);

    dist[X * V1 + 0] = 0;
    pq.push(0, X, 0);

    let ans = -1;

    while (!pq.isEmpty()) {
        const cur = pq.pop();
        const d = cur.time;
        const u = cur.u;
        const c = cur.cost;

        if (d > dist[u * V1 + c]) continue;

        if (u === Y) {
            ans = d;
            break;
        }

        let e = head[u];
        while (e !== -1) {
            const v = to[e];
            const nc = c + costEdge[e];
            if (nc <= V) {
                const nd = d + timeEdge[e];
                const idx = v * V1 + nc;
                if (nd < dist[idx]) {
                    dist[idx] = nd;
                    pq.push(nd, v, nc);
                }
            }
            e = nxt[e];
        }
    }

    console.log(ans);
}

